import{_ as t,o as s,a as l,b as n}from"./app.DKoEZOcr.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"特殊寄存器访问","link":"/api/SIMD-API/basic_api/special_register_access/special_register_access"},{"text":"SetCtrlSpr(ISASI)","link":"/api/SIMD-API/basic_api/special_register_access/SetCtrlSpr_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/special_register_access/SetCtrlSpr_ISASI.md","filePath":"api/SIMD-API/basic_api/special_register_access/SetCtrlSpr_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),p={name:"api/SIMD-API/basic_api/special_register_access/SetCtrlSpr_ISASI.md"};function e(d,a,i,r,c,h){return s(),l("div",null,[...a[0]||(a[0]=[n(`<div><article class="markdown-body"><h1>SetCtrlSpr(ISASI)</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_common_intf.h&quot;</code>。</p><p>对CTRL寄存器（控制寄存器）的特定比特位进行设置。通过模板参数startBit和endBit指定目标比特位范围，将运行参数value（超出比特位范围会出现编译报错）写入CTRL寄存器对应位置。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="w"> </span><span class="n">startBit</span><span class="p">,</span><span class="w"> </span><span class="kt">int8_t</span><span class="w"> </span><span class="n">endBit</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="k">static</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetCtrlSpr</span><span class="p">(</span><span class="kt">int64_t</span><span class="w"> </span><span class="n">value</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>startBit</td><td>起始比特位索引。</td></tr><tr><td>endBit</td><td>终止比特位索引。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>value</td><td>输入</td><td>起止比特位上新设置的值。</td></tr></tbody></table><div data-filter="950"><p><strong>表3</strong> Ascend 950PR/Ascend 950DT常用CTRL寄存器比特位说明<a id="tab-950"></a></p><table><thead><tr><th>CTRL寄存器比特位</th><th>功能</th><th>默认值</th><th>配合使用的API</th></tr></thead><tbody><tr><td>CTRL[8:6]</td><td>用于控制数据从L0C Buffer/Unified Buffer（UB）/L1 Buffer搬运至Global Memory时原子操作的启用及数据类型选择。<br>• 3&#39;b000：不开启原子操作；<br>• 3&#39;b001：开启原子操作，数据类型为float；<br>• 3&#39;b010：开启原子操作，数据类型为half；<br>• 3&#39;b011：开启原子操作，数据类型为int16_t；<br>• 3&#39;b100：开启原子操作，数据类型为int32_t；<br>• 3&#39;b101：开启原子操作，数据类型为int8_t；<br>• 3&#39;b110：开启原子操作，数据类型为bfloat16_t。</td><td>3&#39;b000</td><td>配合使用API：<br>• 数据搬运API。</td></tr><tr><td>CTRL[10:9]</td><td>用于控制原子操作的类型，仅在CTRL[8:6]开启原子操作时生效。<br>• 2&#39;b00：选择ADD操作；<br>• 2&#39;b01：选择MAX操作；<br>• 2&#39;b10：选择MIN操作。</td><td>2&#39;b00</td><td>不涉及</td></tr><tr><td>CTRL[45]</td><td>用于控制左右矩阵数据做Mmad计算时的处理方式。<br>• 1&#39;b0：按照原数据类型进行处理；<br>• 1&#39;b1：左右矩阵数据均为fp8_e4m3fn_t时，数据视为hifloat8_t进行矩阵乘法计算。其他场景按照原数据类型进行处理。</td><td>1&#39;b0</td><td>不涉及</td></tr><tr><td>CTRL[48]</td><td>用于控制浮点数计算和浮点数精度转换时的饱和模式，仅在CTRL[60]开启时生效。<br>• 1&#39;b0：饱和模式，inf输出会被饱和为±MAX，NaN输出会被饱和为0；<br>• 1&#39;b1：非饱和模式，inf/NaN保持原输出。<br><br>该控制位仅支持如下数据类型：<br>•浮点数计算时支持half数据类型；<br>•浮点数精度转换时支持如下数据类型：hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、half、bfloat16_t。</td><td>1&#39;b0</td><td>配合使用的API：<br>• 矢量计算API；<br>• 原子操作API；<br>• 精度转换指令。<br><br>使用约束：<br>• 需要满足数据类型限制。<br>• 执行原子操作过程中，如果需要重新配置该控制位，需要调用<a href="../cache_control/DataCacheCleanAndInvalid.html">DataCacheCleanAndInvalid</a>先清除当前Cache Line状态并将当前数据写出，防止饱和模式变更影响当前数据。具体调用示例可参考<a href="#example2">原子操作中，half类型配置全局非饱和模式示例。</a>。</td></tr><tr><td>CTRL[50]</td><td>用于控制浮点数精度转换时的NaN饱和模式，在CTRL[48]设置为饱和模式时生效。<br>• 1&#39;b0：NaN输出会被转换为0.0；<br>• 1&#39;b1：NaN输出会保持NaN。<br><br>该控制位仅支持如下数据类型：<br>fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t。</td><td>1&#39;b0</td><td>精度转换指令（需要满足数据类型限制）。</td></tr><tr><td>CTRL[53]</td><td>用于控制整数计算指令的饱和模式。<br>• 1&#39;b0：截断模式，溢出值按目标数据类型位数截断，保留低位，舍弃高位；<br>• 1&#39;b1：饱和模式，溢出值饱和到±MAX。</td><td>1&#39;b0</td><td>矢量计算API（输入输出数据类型为整数）。</td></tr><tr><td>CTRL[59]</td><td>用于控制浮点数转整数或整数转整数时的精度转换饱和模式，仅在CTRL[60]开启时生效。<br>• 1&#39;b0：饱和模式：溢出值饱和到±MAX；<br>• 1&#39;b1：截断模式：溢出值按目标数据类型位数截断，保留低位，舍弃高位。</td><td>1&#39;b0</td><td>精度转换指令。</td></tr><tr><td>CTRL[60]</td><td>用于控制饱和模式的全局生效方式。<br>• 1&#39;b0：单指令设置饱和；<br>• 1&#39;b1：全局设置饱和。</td><td>1&#39;b1</td><td>该控制位可与Reg矢量计算API <a href="../reg_vector_compute/type_conversion/Cast.html">Cast</a>配合使用，或与CTRL[48]、CTRL[59]配合使用，具体配置信息参考<a href="#table231122118201">Ascend 950PR/Ascend 950DT饱和模式全局或单指令生效配置表</a>。</td></tr></tbody></table></div><div data-filter="A3"><p><strong>表4</strong> Atlas A3 训练系列产品/Atlas A3 推理系列产品常用CTRL寄存器比特位说明</p><table><thead><tr><th>CTRL寄存器比特位</th><th>功能</th><th>默认值</th><th>配合使用的API</th></tr></thead><tbody><tr><td>CTRL[48]</td><td>用于控制浮点数计算和浮点数精度转换时的饱和模式。<br>• 1&#39;b0：饱和模式，inf输出会被饱和为±MAX， NaN输出会被饱和为0；<br>• 1&#39;b1：非饱和模式，inf/NaN保持原输出。<br><br>该控制位仅支持如下数据类型：<br>•浮点数计算时支持half、bfloat16_t数据类型；<br>•浮点数精度转换时支持如下数据类型：half、bfloat16_t。</td><td>1&#39;b0</td><td>不涉及</td></tr></tbody></table><p><strong>注：针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，推荐使用<a href="./SetSaturationFlag_ISASI.html">SetSaturationFlag</a>和<a href="./GetSaturationFlag_ISASI.html">GetSaturationFlag</a>来设置和获取CTRL[48]以控制饱和模式。</strong></p></div><div data-filter="910b"><p><strong>表5</strong> Atlas A2 训练系列产品/Atlas A2 推理系列产品常用CTRL寄存器比特位说明</p><table><thead><tr><th>CTRL寄存器比特位</th><th>功能</th><th>默认值</th><th>配合使用的API</th></tr></thead><tbody><tr><td>CTRL[48]</td><td>用于控制浮点数计算和浮点数精度转换时的饱和模式。<br>• 1&#39;b0：饱和模式，inf输出会被饱和为±MAX， NaN输出会被饱和为0；<br>• 1&#39;b1：非饱和模式，inf/NaN保持原输出。<br><br>该控制位仅支持如下数据类型：<br>•浮点数计算时支持half、bfloat16_t数据类型；<br>•浮点数精度转换时支持如下数据类型：half、bfloat16_t。</td><td>1&#39;b0</td><td>不涉及</td></tr></tbody></table><p><strong>注：针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，推荐使用<a href="./SetSaturationFlag_ISASI.html">SetSaturationFlag</a>和<a href="./GetSaturationFlag_ISASI.html">GetSaturationFlag</a>来设置和获取CTRL[48]以控制饱和模式。</strong></p></div><div data-filter="950"><p><strong>表6</strong> Ascend 950PR/Ascend 950DT饱和模式全局或单指令生效配置表<a id="table231122118201"></a></p><table><thead><tr><th>全局开启位</th><th>控制位</th><th>功能描述</th></tr></thead><tbody><tr><td>CTRL[60] = 1&#39;b0</td><td>Reg矢量计算Cast API的trait模板参数中satMode设置为SatMode::NO_SAT。</td><td>单指令非饱和模式。</td></tr><tr><td>CTRL[60] = 1&#39;b0</td><td>Reg矢量计算Cast API的trait模板参数中satMode设置为SatMode::SAT。</td><td>单指令饱和模式。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[48] = 1&#39;b1</td><td>全局非饱和模式（浮点数计算和浮点数精度转换）。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[48] = 1&#39;b0</td><td>全局饱和模式（浮点数计算和浮点数精度转换）。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[59] = 1&#39;b1</td><td>全局非饱和模式（浮点数转整数或整数转整数时的精度转换）。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[59] = 1&#39;b0</td><td>全局饱和模式（浮点数转整数或整数转整数时的精度转换）。</td></tr></tbody></table></div><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>本接口为寄存器访问接口，不涉及张量数据类型操作。参数value类型固定为int64_t。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT仅支持CTRL[8:6]、CTRL[10:9]、CTRL[45]、CTRL[48]、CTRL[50]、CTRL[53]、CTRL[59]、CTRL[60]比特位。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品仅支持CTRL[48]比特位。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品仅支持CTRL[48]比特位。</li></ul></div><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT对于CTRL[8:6]和CTRL[10:9]的设置，已封装原子操作API，建议通过这些原子操作API进行配置。 <ul><li><a href="../atomic_operations/SetAtomicType.html">SetAtomicType</a></li><li><a href="../atomic_operations/DisableDmaAtomic.html">DisableDmaAtomic</a></li><li><a href="../atomic_operations/SetAtomicAdd.html">SetAtomicAdd</a></li><li><a href="../atomic_operations/SetAtomicMax_ISASI.html">SetAtomicMax</a></li><li><a href="../atomic_operations/SetAtomicMin_ISASI.html">SetAtomicMin</a></li></ul></li></ul></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>如下示例中开启非饱和模式，数据类型为half。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">SetCtrlSpr</span><span class="o">&lt;</span><span class="mi">48</span><span class="p">,</span><span class="w"> </span><span class="mi">48</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
</code></pre></div></li><li><p><span id="example2"></span>原子操作中，half类型配置全局非饱和模式示例。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">SetCtrlSpr</span><span class="o">&lt;</span><span class="mi">6</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">2</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetAtomicAdd</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCacheCleanAndInvalid</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheLine</span><span class="o">::</span><span class="n">ENTIRE_DATA_CACHE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DcciDst</span><span class="o">::</span><span class="n">CACHELINE_ATOMIC</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstTensor</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetCtrlSpr</span><span class="o">&lt;</span><span class="mi">48</span><span class="p">,</span><span class="w"> </span><span class="mi">48</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
<span class="p">...</span>
</code></pre></div></li></ul><p>更多示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/09_utils/ctrl_spr">CtrlSpr样例</a>。</p></article></div>`,1)])])}const A=t(p,[["render",e]]);export{b as __pageData,A as default};
